        (("nova", "Parallax, why do you watch things move?"), ("parallax", "To see how far away they are."), ("nova", "Oh. That's lovely. Can you teach me?"), ("parallax", "Sit still for six months. Then we will talk.")),
        (("parallax", "Nova, you ask a great many questions."), ("nova", "Is that a problem?"), ("parallax", "No. I answer the good ones. Keep going.")),
        (("nova", "Parallax, what's the best view on the ship?"), ("parallax", "The warm panel by the scanner. Looking aft."), ("nova", "Why aft?"), ("parallax", "Because everything we have done is behind us, getting smaller. It is very satisfying.")),
        (("parallax", "Nova, you look out of the window more than anyone except me."), ("nova", "I'm learning from you."), ("parallax", "Good. You may have the second-best seat.")),
